def design_assets(kind,xyz=(0,0,0),yaw_deg=0,**opts):
    """xy is center, except hearth at the two-wall corner and sconce on its wall. All furniture faces local -Y.
    hearth's masonry follows +X,+Y, stove points diagonally +X,+Y. Sofa width overrides design sizes.
    """
    B=_IFBuilder()
    if kind=='sofa':
        s=opts.get('style','main');_if_sofa(B,float(opts.get('width',1.62 if s=='love' else 2.13)),s)
    elif kind=='hearth':_if_hearth(B,float(opts.get('height',2.48)),float(opts.get('left_length',1.42)),float(opts.get('right_length',1.42)),opts.get('stone_return_length'))
    elif kind in ('coffee_table','end_table'):_if_table(B,kind,opts.get('style','glass')=='wood')
    elif kind=='media':_if_media(B)
    elif kind=='curio':_if_curio(B)
    elif kind=='sconce':_if_sconce(B)
    else:raise ValueError('Unknown cabin asset '+str(kind))
    return B.finish('Cabin | '+kind.replace('_',' ').capitalize()+' '+opts.get('style',''),xyz,yaw_deg)

